#!/usr/bin/env python3
import whisper
import json
import re

# Chapter titles to find
chapters = [
    "What we'll do",
    "How we'll get there",
    "Getting a floor plan",
    "Getting started",
    "Basic Navigation",
    "Import your plan into Blender",
    "Basic transform operations",
    "Setting up the plan and units",
    "It all starts with a plane",
    "Scaling the plane to real dimensions",
    "Getting the plan in place",
    "Tracing the outline",
    "Tracing inner walls",
    "Break",
    "Continue tracing inner walls",
    "Remove doubled vertices",
    "Save",
    "Make the floor",
    "Remove unnecessary geometry",
    "Make the floor's faces",
    "Make the background",
    "Extruding the walls in Z",
    "Reviewing face orientation",
    "Adding thickness to walls with Modifiers",
    "Fixing face orientation errors",
    "Note on face orientation",
    "Save As",
    "If you need thick and thin walls",
    "Great job!"
]

print("Loading Whisper model...")
model = whisper.load_model("tiny")

print("Transcribing audio...")
result = model.transcribe("/root/tutorial_audio.wav", language="en", verbose=True)

# Save full transcript for debugging
with open("/root/full_transcript.json", "w") as f:
    json.dump(result, f, indent=2)

print("\n\nAnalyzing transcript for chapter markers...")

# Function to find best timestamp for a chapter
def find_chapter_timestamp(segments, chapter_title, search_start=0):
    # Create search terms from chapter title
    title_lower = chapter_title.lower()

    # Special handling for common patterns
    search_patterns = []

    if chapter_title == "What we'll do":
        search_patterns = [r"what we'?ll do", r"what we are going to do", r"what we will do"]
    elif chapter_title == "How we'll get there":
        search_patterns = [r"how we'?ll get there", r"how we will get there", r"how we are going to get there"]
    elif chapter_title == "Getting a floor plan":
        search_patterns = [r"getting a floor plan", r"get a floor plan", r"floor plan"]
    elif chapter_title == "Getting started":
        search_patterns = [r"getting started", r"get started", r"let'?s get started"]
    elif chapter_title == "Basic Navigation":
        search_patterns = [r"basic navigation", r"navigation"]
    elif chapter_title == "Import your plan into Blender":
        search_patterns = [r"import.{0,20}plan.{0,20}blender", r"import.{0,10}blender"]
    elif chapter_title == "Basic transform operations":
        search_patterns = [r"basic transform", r"transform operations"]
    elif chapter_title == "Setting up the plan and units":
        search_patterns = [r"setting up.{0,20}plan.{0,20}units", r"plan and units", r"set.{0,10}units"]
    elif chapter_title == "It all starts with a plane":
        search_patterns = [r"it all starts with a plane", r"starts with a plane"]
    elif chapter_title == "Scaling the plane to real dimensions":
        search_patterns = [r"scaling.{0,20}plane.{0,20}real dimensions", r"scale.{0,20}real dimensions"]
    elif chapter_title == "Getting the plan in place":
        search_patterns = [r"getting.{0,10}plan in place", r"plan in place"]
    elif chapter_title == "Tracing the outline":
        search_patterns = [r"trac(ing|e).{0,10}outline", r"outline"]
    elif chapter_title == "Tracing inner walls":
        search_patterns = [r"trac(ing|e).{0,10}inner walls", r"inner walls"]
    elif chapter_title == "Break":
        search_patterns = [r"take a break", r"break time", r"\bbreak\b"]
    elif chapter_title == "Continue tracing inner walls":
        search_patterns = [r"continue.{0,20}trac(ing|e).{0,10}inner", r"continue.{0,10}inner walls"]
    elif chapter_title == "Remove doubled vertices":
        search_patterns = [r"remove.{0,20}doubled.{0,10}vertic", r"doubled.{0,10}vertic", r"remove doubles"]
    elif chapter_title == "Save":
        search_patterns = [r"save", r"saving"]
    elif chapter_title == "Make the floor":
        search_patterns = [r"make.{0,10}floor", r"creating.{0,10}floor"]
    elif chapter_title == "Remove unnecessary geometry":
        search_patterns = [r"remove.{0,20}unnecessary.{0,10}geometry", r"unnecessary.{0,10}geometry"]
    elif chapter_title == "Make the floor's faces":
        search_patterns = [r"make.{0,10}floor.{0,5}faces", r"floor.{0,5}faces"]
    elif chapter_title == "Make the background":
        search_patterns = [r"make.{0,10}background", r"background"]
    elif chapter_title == "Extruding the walls in Z":
        search_patterns = [r"extrud(ing|e).{0,20}walls.{0,10}z", r"extrud(ing|e).{0,10}z"]
    elif chapter_title == "Reviewing face orientation":
        search_patterns = [r"review(ing)?.{0,20}face.{0,10}orientation", r"face.{0,10}orientation"]
    elif chapter_title == "Adding thickness to walls with Modifiers":
        search_patterns = [r"add(ing)?.{0,20}thickness.{0,20}modifier", r"thickness.{0,20}modifier", r"solidify"]
    elif chapter_title == "Fixing face orientation errors":
        search_patterns = [r"fix(ing)?.{0,20}face.{0,10}orientation", r"fix.{0,10}orientation"]
    elif chapter_title == "Note on face orientation":
        search_patterns = [r"note.{0,10}face.{0,10}orientation", r"note.{0,10}orientation"]
    elif chapter_title == "Save As":
        search_patterns = [r"save as", r"saving as"]
    elif chapter_title == "If you need thick and thin walls":
        search_patterns = [r"thick and thin walls", r"thick.{0,10}thin.{0,10}walls"]
    elif chapter_title == "Great job!":
        search_patterns = [r"great job", r"good job", r"congratulations"]
    else:
        # Default: use title as-is
        search_patterns = [title_lower.replace("'", "'?")]

    # Search through segments
    for seg in segments:
        if seg['start'] < search_start:
            continue

        text_lower = seg['text'].lower()

        for pattern in search_patterns:
            if re.search(pattern, text_lower):
                print(f"  Found '{chapter_title}' at {int(seg['start'])}s: {seg['text'][:100]}")
                return int(seg['start'])

    return None

# Find timestamps for each chapter
chapter_data = []
last_timestamp = 0

for i, chapter_title in enumerate(chapters):
    timestamp = find_chapter_timestamp(result['segments'], chapter_title, last_timestamp)

    if timestamp is None:
        # If not found, use heuristic based on video duration and position
        print(f"  Warning: Could not find '{chapter_title}', using estimated timestamp")
        # Estimate based on position in list
        estimated = int((i / len(chapters)) * 1382)
        timestamp = max(estimated, last_timestamp)

    # First chapter always starts at 0
    if i == 0:
        timestamp = 0

    chapter_data.append({
        "time": timestamp,
        "title": chapter_title
    })

    last_timestamp = timestamp

# Ensure monotonicity
for i in range(1, len(chapter_data)):
    if chapter_data[i]['time'] <= chapter_data[i-1]['time']:
        chapter_data[i]['time'] = chapter_data[i-1]['time'] + 1

# Create output JSON
output = {
    "video_info": {
        "title": "In-Depth Floor Plan Tutorial Part 1",
        "duration_seconds": 1382
    },
    "chapters": chapter_data
}

# Write output
with open("/root/tutorial_index.json", "w") as f:
    json.dump(output, f, indent=2)

print("\n\nChapter index saved to /root/tutorial_index.json")
print(json.dumps(output, indent=2))
